<script lang="ts">
  import { Accordion } from 'bits-ui';
  import ChevronDownIcon from '@lucide/svelte/icons/chevron-down';
  import { formatDate } from '$lib/dates';
  import AmountInput from '$lib/components/forms/amount-input.svelte';
  import Disclosure from '$lib/components/shared/disclosure.svelte';
  import LoadingScope from '$lib/components/shared/loading-scope.svelte';
  import DatePicker from '$lib/components/forms/date-picker.svelte';
  import ChoiceSelect from '$lib/components/forms/choice-select.svelte';
  import { Checkbox } from '$lib/components/ui/checkbox';
  import {getContext as privacyContext} from 'svelte';
  import {concealed,PRIVACY_CONTEXT,type PrivacyState} from '$lib/privacy';
  const privacy=privacyContext<PrivacyState>(PRIVACY_CONTEXT);
  import { getContext } from 'svelte';import { AUTH_UI_CONTEXT,type AuthUiState } from '$lib/i18n/auth';import { financeText } from '$lib/i18n/finance';import { uxText } from '$lib/i18n/ux';import { Button } from '$lib/components/ui/button';import * as Card from '$lib/components/ui/card';import * as Field from '$lib/components/ui/field';import { Input } from '$lib/components/ui/input';import * as AlertDialog from '$lib/components/ui/alert-dialog';
  import PageHeader from '$lib/components/shared/page-header.svelte';import MoneyDisplay from '$lib/components/shared/money-display.svelte';import EmptyState from '$lib/components/shared/empty-state.svelte';import ErrorState from '$lib/components/shared/error-state.svelte';import LoadingSkeleton from '$lib/components/shared/loading-skeleton.svelte';import StatusBadge from '$lib/components/shared/status-badge.svelte';
  type WorkspaceState={selectedId:string;ready:boolean};type RecurringRule={id:string;name:string;type:string;status:string;currency:string;amount:string;frequency:string;interval:number;anchorDate:string;accountId:string};type Bill={id:string;billId:string;frequency:'once'|'week'|'month'|'year';interval:number;anchorDate:string;schedulePaymentAccountId:string|null;name:string;amount:string;currency:string;dueOn:string;status:string;overdue:boolean;paymentAccountId:string|null;expectedPaymentOn:string|null;deferrableUntil:string|null;transactionId:string|null;recurringRuleId:string|null};const workspace=getContext<WorkspaceState>('capybudget-workspaces'),ui=getContext<AuthUiState>(AUTH_UI_CONTEXT),t=(key:Parameters<typeof financeText>[1])=>financeText(ui.locale,key);
  const ux=(key:Parameters<typeof uxText>[1])=>uxText(ui.locale,key);
  let items:Bill[]=$state([]),accounts:any[]=$state([]),transactions:any[]=$state([]),recurringRules:RecurringRule[]=$state([]),loading=$state(true),error=$state(''),name=$state(''),amount=$state(''),dueOn=$state(''),frequency=$state<'once'|'week'|'month'|'year'>('month'),saving=$state(false),emailEnabled=$state(true),pushEnabled=$state(false),pushBusy=$state(false),preferenceVersion=$state(1),paidTarget=$state<Bill|null>(null),archiveTarget=$state<Bill|null>(null);
  let shareSeries=$state<Record<string,boolean>>({}),forecastSaving=$state(''),notice=$state('');
  let occurrenceCount=$state<number|undefined>(undefined);
  let expandedSeries=$state<string[]>([]);
  // Match the stored name exactly and use the calendar day without timezone conversion.
  const billGroupKey=(billName:string,date:string)=>JSON.stringify([billName,Number(date.slice(8,10))]);
  const billSeries=$derived.by(()=>{
    const groups=new Map<string,Bill[]>();
    for(const item of items){const key=billGroupKey(item.name,item.dueOn);const rows=groups.get(key)??[];rows.push(item);groups.set(key,rows);}
    return [...groups].map(([id,rows])=>({id,name:rows[0].name,day:Number(rows[0].dueOn.slice(8,10)),rows:rows.toSorted((a,b)=>a.dueOn.localeCompare(b.dueOn)),unpaid:rows.filter(row=>row.status==='unpaid').length}));
  });
  const todayIso=()=>new Date().toISOString().slice(0,10);
  async function load(){if(!workspace.ready||!workspace.selectedId)return;loading=true;try{const [r,p,a,tr,rr]=await Promise.all([fetch(`/api/workspaces/${workspace.selectedId}/bills`),fetch(`/api/workspaces/${workspace.selectedId}/notification-preferences`),fetch(`/api/workspaces/${workspace.selectedId}/accounts`),fetch(`/api/workspaces/${workspace.selectedId}/transactions?type=expense&limit=100`),fetch(`/api/workspaces/${workspace.selectedId}/recurring-rules`)]);if(!r.ok||!p.ok)throw new Error(t('error'));items=(await r.json()).items;accounts=a.ok?(await a.json()).items??[]:[];transactions=tr.ok?(await tr.json()).items??[]:[];recurringRules=rr.ok?(await rr.json()).items??[]:[];const prefs=await p.json();preferenceVersion=prefs.version??1;emailEnabled=prefs.emailBillReminders;pushEnabled=prefs.pushBillReminders;}catch(e){error=e instanceof Error?e.message:t('error');}finally{loading=false;}}
  $effect(()=>{void (workspace as {revision?:number}).revision;if(workspace.ready&&workspace.selectedId)void load();});
  async function create(event:SubmitEvent){event.preventDefault();if(saving)return;saving=true;error='';try{const r=await fetch(`/api/workspaces/${workspace.selectedId}/bills`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,amount,dueOn,frequency,occurrenceCount:frequency==='once'?1:occurrenceCount,reminderDays:[3,0]})});const b=await r.json();if(!r.ok)throw new Error(b.message);expandedSeries=[...new Set([...expandedSeries,billGroupKey(b.bill?.name??name.trim(),dueOn)])];name='';amount='';occurrenceCount=undefined;await load();}catch(e){error=e instanceof Error?e.message:t('error');}finally{saving=false;}}
  async function action(item:Bill,verb:'paid'|'skip'|'reopen'){const r=await fetch(`/api/workspaces/${workspace.selectedId}/bill-occurrences/${item.id}/${verb}`,{method:'POST'});if(!r.ok){const body=await r.json();error=body.message??t('error');}await load();}
  async function saveForecastSettings(item:Bill){
    if(forecastSaving)return;error='';notice='';
    if(item.recurringRuleId&&!matchingRecurringRules(item).some(rule=>rule.id===item.recurringRuleId)){error=t('recurringMatchHint');return;}
    const shared=!!shareSeries[item.id];
    const body:any={scope:shared?'series':'occurrence',paymentAccountId:item.paymentAccountId||null,expectedPaymentOn:item.expectedPaymentOn||null,deferrableUntil:item.deferrableUntil||null,recurringRuleId:item.recurringRuleId||null};
    if(!shared&&item.transactionId)body.transactionId=item.transactionId;
    forecastSaving=item.id;
    try{
      const response=await fetch(`/api/workspaces/${workspace.selectedId}/bill-occurrences/${item.id}/forecast-settings`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(body)});
      const result=await response.json();if(!response.ok)throw new Error(result.message??t('error'));
      shareSeries[item.id]=false;
      notice=shared?t('seriesSettingsSaved').replace('{count}',String(result.affectedCount)):t('forecastSettingsSaved');
      await load();
    }catch(reason){error=reason instanceof Error?reason.message:t('error');}
    finally{forecastSaving='';}
  }
  function sameAmount(a:string,b:string){const normalize=(value:string)=>{const [whole,fraction='']=value.split('.');return `${whole}.${fraction.replace(/0+$/,'')}`};return normalize(a)===normalize(b);}
  function matchingRecurringRules(item:Bill){
    const paymentAccount=item.paymentAccountId||item.schedulePaymentAccountId;
    return recurringRules.filter(rule=>item.frequency!=='once'&&rule.type==='expense'&&rule.status==='active'&&rule.currency===item.currency&&sameAmount(rule.amount,item.amount)&&rule.frequency===item.frequency&&Number(rule.interval)===Number(item.interval)&&String(rule.anchorDate).slice(0,10)===String(item.anchorDate).slice(0,10)&&(!paymentAccount||rule.accountId===paymentAccount));
  }
  function matchingHint(item:Bill){
    const frequencyLabel=item.frequency==='week'?t('week'):item.frequency==='month'?t('month'):item.frequency==='year'?t('year'):t('once');
    return `${matchingRecurringRules(item).length?t('recurringMatchHint'):t('noRecurringMatch')} ${t('startsOn')}: ${formatDate(item.anchorDate)} · ${item.interval} × ${frequencyLabel}.`;
  }
  function paymentAccountChanged(item:Bill){
    if(item.recurringRuleId&&!matchingRecurringRules(item).some(rule=>rule.id===item.recurringRuleId))item.recurringRuleId=null;
  }
  async function confirmArchive(){const target=archiveTarget;if(!target)return;archiveTarget=null;const r=await fetch(`/api/workspaces/${workspace.selectedId}/bills/${target.billId}`,{method:'DELETE'});if(!r.ok)error=t('error');await load();}
  async function preference(){const next=!emailEnabled;const r=await fetch(`/api/workspaces/${workspace.selectedId}/notification-preferences`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({version:preferenceVersion,emailBillReminders:next})});if(r.ok){const saved=await r.json();preferenceVersion=saved.version;emailEnabled=next;}else{error=t('error');await load();}}
  function decodeKey(value:string){const normalized=value.replace(/-/g,'+').replace(/_/g,'/');const raw=atob(normalized+'='.repeat((4-normalized.length%4)%4));return Uint8Array.from(raw,(c)=>c.charCodeAt(0));}
  async function togglePush(){if(pushBusy)return;pushBusy=true;error='';try{if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw new Error(t('pushUnsupported'));const registration=await navigator.serviceWorker.ready;let subscription=await registration.pushManager.getSubscription();if(pushEnabled){if(subscription){const removed=await fetch(`/api/workspaces/${workspace.selectedId}/push-subscriptions`,{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({endpoint:subscription.endpoint})});if(!removed.ok)throw new Error(t('error'));await subscription.unsubscribe();}const saved=await fetch(`/api/workspaces/${workspace.selectedId}/notification-preferences`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({version:preferenceVersion,pushBillReminders:false})});if(!saved.ok)throw new Error(t('error'));preferenceVersion=(await saved.json()).version;pushEnabled=false;return;}const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error(t('pushPermission'));const keyResponse=await fetch('/api/push/vapid-public-key');if(!keyResponse.ok)throw new Error((await keyResponse.json()).message??t('pushUnconfigured'));const {publicKey}=await keyResponse.json();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:decodeKey(publicKey)});const stored=await fetch(`/api/workspaces/${workspace.selectedId}/push-subscriptions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(subscription.toJSON())});if(!stored.ok)throw new Error((await stored.json()).message??t('error'));const saved=await fetch(`/api/workspaces/${workspace.selectedId}/notification-preferences`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({version:preferenceVersion,pushBillReminders:true})});if(!saved.ok)throw new Error(t('error'));preferenceVersion=(await saved.json()).version;pushEnabled=true;}catch(e){error=e instanceof Error?e.message:t('error');await load();}finally{pushBusy=false;}}
</script>
<LoadingScope active={!!loading || !!saving || !!forecastSaving} />
<svelte:head><title>CapyBudget · {t('bills')}</title></svelte:head>
<PageHeader eyebrow={t('financeEyebrow').toUpperCase()} title={t('bills')} description={t('billIntro')} />
{#if error}<ErrorState title={ux('errorTitle')} message={error} retryLabel={ux('retry')} onRetry={load} />{/if}
{#if notice}<p role="status" class="forecast-notice">{notice}</p>{/if}
<div class="grid"><Card.Root><Card.Header><Card.Title>{t('addBill')}</Card.Title><Card.Description>{t('billFormHint')}</Card.Description></Card.Header><Card.Content><form onsubmit={create}><Field.FieldGroup><Field.Field><Field.FieldLabel for="bill-name">{t('name')}</Field.FieldLabel><Input id="bill-name" bind:value={name} maxlength={120} required /></Field.Field><Field.Field><Field.FieldLabel for="bill-amount">{t('amount')}</Field.FieldLabel><AmountInput id="bill-amount" inputmode="decimal"  type={privacy.hidden?'password':'text'} bind:value={amount} required /></Field.Field><Field.Field><Field.FieldLabel for="bill-due">{t('dueOn')}</Field.FieldLabel><DatePicker id="bill-due" bind:value={dueOn} required /></Field.Field><Field.Field><Field.FieldLabel for="bill-frequency">{t('recurrence')}</Field.FieldLabel><ChoiceSelect id="bill-frequency" bind:value={frequency} items={[{value: "once", label: String(t('once'))}, {value: "week", label: String(t('week'))}, {value: "month", label: String(t('month'))}, {value: "year", label: String(t('year'))}]} /></Field.Field><Field.Field><Field.FieldLabel for="bill-count">{t('billCount')}</Field.FieldLabel><Input id="bill-count" type="number" min={1} max={300} step={1} value={frequency==='once'?1:occurrenceCount??''} oninput={(event)=>{occurrenceCount=event.currentTarget.value===''?undefined:Number(event.currentTarget.value);}} disabled={saving||frequency==='once'} placeholder={t('billCountPlaceholder')} aria-describedby="bill-count-hint" /><Field.FieldDescription id="bill-count-hint">{frequency==='once'?t('billCountOnceHint'):t('billCountHint')}</Field.FieldDescription></Field.Field></Field.FieldGroup><Button class="submit" type="submit" disabled={saving||!workspace.selectedId}>{saving?'…':t('addBill')}</Button></form><label class="preference"><Checkbox checked={emailEnabled} onCheckedChange={preference} /> {t('emailReminders')}</label><label class="preference"><Checkbox checked={pushEnabled} onCheckedChange={togglePush} disabled={pushBusy} /> {t('pushReminders')}{pushBusy?'…':''}</label></Card.Content></Card.Root>
<section class="list" aria-label={t('bills')}>{#if loading}<LoadingSkeleton rows={3} label={t('loading')} />{:else if !items.length}<Card.Root><Card.Content><EmptyState title={t('bills')} body={t('emptyBills')} actionLabel={t('addBill')} actionHref="#bill-name" /></Card.Content></Card.Root>{:else}<Accordion.Root type="multiple" bind:value={expandedSeries}>{#each billSeries as series (series.id)}
<Accordion.Item value={series.id} class="bill-series">
<Accordion.Header level={2} class="bill-series-header"><Accordion.Trigger class="bill-series-trigger"><span class="bill-series-title"><strong>{series.name}</strong><small>{ui.locale==='id'?`Tanggal ${series.day}`:`Day ${series.day}`} · {series.rows.length} {t('bills')} · {series.unpaid} {t('unpaidLabel')} · {formatDate(series.rows[0].dueOn)} – {formatDate(series.rows.at(-1)?.dueOn)}</small></span><ChevronDownIcon class="bill-series-chevron" aria-hidden="true" /></Accordion.Trigger></Accordion.Header>
<Accordion.Content class="bill-series-content"><div class="bill-series-items">{#each series.rows as item (item.id)}<Card.Root><Card.Header><div class="title-row"><div><Card.Title>{formatDate(item.dueOn)}</Card.Title><Card.Description>{#if item.overdue}<StatusBadge tone="expense">{t('overdue')}</StatusBadge>{:else if item.dueOn===todayIso()}{t('dueToday')}{:else}{t('dueOnLabel')} {formatDate(item.dueOn)}{/if}</Card.Description></div><MoneyDisplay amount={item.amount} currency={item.currency} type={item.overdue?'expense':null} size="lg" /></div></Card.Header><Card.Content><Disclosure class="forecast-settings">{#snippet title()}{ui.locale==='id'?'Atur asumsi prakiraan':'Forecast and payment matching'}{/snippet}<Field.FieldGroup><Field.Field><Field.FieldLabel for={`bill-account-${item.id}`}>{ui.locale==='id'?'Akun pembayaran':'Payment account'}</Field.FieldLabel><ChoiceSelect id={`bill-account-${item.id}`} bind:value={item.paymentAccountId} onValueChange={()=>paymentAccountChanged(item)} items={[{value: '', label: String(ui.locale==='id'?'Belum ditentukan':'Unassigned')}, ...(accounts.filter((account:any)=>account.currency===item.currency&&['cash','bank','e_wallet','savings'].includes(account.kind))).flatMap((account) => [{value: account.id, label: String(account.name)}])]} /><Field.FieldDescription>{t('paymentMatchChangeHint')}</Field.FieldDescription></Field.Field><Field.Field><Field.FieldLabel for={`bill-expected-${item.id}`}>{ui.locale==='id'?'Tanggal pembayaran yang diperkirakan':'Expected payment date'}</Field.FieldLabel><DatePicker id={`bill-expected-${item.id}`} bind:value={item.expectedPaymentOn} /></Field.Field><Field.Field><Field.FieldLabel for={`bill-flexible-${item.id}`}>{ui.locale==='id'?'Dapat ditunda sampai (opsional)':'Flexible until (optional)'}</Field.FieldLabel><DatePicker id={`bill-flexible-${item.id}`} bind:value={item.deferrableUntil} /></Field.Field><Field.Field><Field.FieldLabel for={`bill-rule-${item.id}`}>{ui.locale==='id'?'Pengeluaran berulang yang sama':'Matching recurring expense'}</Field.FieldLabel><ChoiceSelect id={`bill-rule-${item.id}`} bind:value={item.recurringRuleId} disabled={item.frequency==='once'} aria-describedby={`bill-rule-hint-${item.id}`} items={[{value: '', label: String(ui.locale==='id'?'Tidak ada':'None')}, ...(matchingRecurringRules(item)).flatMap((rule) => [{value: rule.id, label: String(rule.name) + " · " + String(rule.frequency) + " · " + String(rule.currency) + " " + String(concealed(rule.amount,privacy.hidden))}])]} /><Field.FieldDescription id={`bill-rule-hint-${item.id}`}>{item.frequency==='once'?t('oneTimeRecurringMatch'):matchingHint(item)}</Field.FieldDescription></Field.Field><Field.Field><Field.FieldLabel for={`bill-transaction-${item.id}`}>{ui.locale==='id'?'Transaksi pembayaran yang sudah ada':'Link existing payment transaction'}</Field.FieldLabel><ChoiceSelect id={`bill-transaction-${item.id}`} bind:value={item.transactionId} disabled={!!shareSeries[item.id]||!!forecastSaving} items={[{value: '', label: String(item.status==='paid'&&item.transactionId?'':t('noTxLinked'))}, ...(transactions.filter((transaction:any)=>transaction.currency===item.currency&&sameAmount(transaction.amount,item.amount)&&(!item.paymentAccountId||transaction.accountId===item.paymentAccountId))).flatMap((transaction) => [{value: transaction.id, label: formatDate(transaction.date) + " · " + String(transaction.merchant||transaction.categoryName||'Expense') + " · " + String(transaction.currency) + " " + String(concealed(transaction.amount,privacy.hidden))}])]} /></Field.Field></Field.FieldGroup>{#if item.status==='unpaid'&&!item.transactionId}
<Field.Field class="series-setting"><label for={`share-series-${item.id}`} class="preference"><Checkbox id={`share-series-${item.id}`} checked={!!shareSeries[item.id]} disabled={!!forecastSaving} onCheckedChange={(checked)=>shareSeries[item.id]=checked} aria-describedby={`share-series-hint-${item.id}`} />{t('applyToSeries')}</label><Field.FieldDescription id={`share-series-hint-${item.id}`}>{t('shareSeriesHint')}</Field.FieldDescription></Field.Field>
{/if}
<Button size="sm" variant="outline" disabled={!!forecastSaving} aria-busy={forecastSaving===item.id} onclick={()=>saveForecastSettings(item)}>{forecastSaving===item.id?t('saving'):shareSeries[item.id]?t('saveSeriesSettings'):ui.locale==='id'?'Simpan asumsi':'Save assumptions'}</Button></Disclosure></Card.Content><Card.Footer class="actions">{#if item.status==='unpaid'}<Button size="sm" onclick={()=>paidTarget=item}>{t('paid')}</Button><Button size="sm" variant="outline" onclick={()=>action(item,'skip')}>{t('skip')}</Button>{:else}<span>{item.status==='paid'?t('paid'):t('skip')}</span><Button size="sm" variant="ghost" onclick={()=>action(item,'reopen')}>{t('reopen')}</Button>{/if}<Button size="sm" variant="ghost" onclick={()=>archiveTarget=item}>{t('archiveBill')}</Button></Card.Footer></Card.Root>{/each}</div></Accordion.Content></Accordion.Item>{/each}</Accordion.Root>{/if}</section></div>
<AlertDialog.Root open={!!paidTarget} onOpenChange={(v)=>{if(!v)paidTarget=null;}}>
  <AlertDialog.Content>
    <AlertDialog.Header><AlertDialog.Title>{t('markPaidTitle')}</AlertDialog.Title><AlertDialog.Description>{t('paymentNote')}</AlertDialog.Description></AlertDialog.Header>
    <AlertDialog.Footer><AlertDialog.Cancel onclick={()=>paidTarget=null}>{t('cancel')}</AlertDialog.Cancel><AlertDialog.Action onclick={()=>{const target=paidTarget;paidTarget=null;if(target)void action(target,'paid');}}>{t('paid')}</AlertDialog.Action></AlertDialog.Footer>
  </AlertDialog.Content>
</AlertDialog.Root>
<AlertDialog.Root open={!!archiveTarget} onOpenChange={(v)=>{if(!v)archiveTarget=null;}}>
  <AlertDialog.Content>
    <AlertDialog.Header><AlertDialog.Title>{t('archiveBillTitle')}</AlertDialog.Title><AlertDialog.Description>{t('archiveBody')}</AlertDialog.Description></AlertDialog.Header>
    <AlertDialog.Footer><AlertDialog.Cancel onclick={()=>archiveTarget=null}>{t('cancel')}</AlertDialog.Cancel><AlertDialog.Action onclick={confirmArchive}>{t('archiveBill')}</AlertDialog.Action></AlertDialog.Footer>
  </AlertDialog.Content>
</AlertDialog.Root>
<style>
:global(.bill-series){margin-bottom:16px;border:2px solid var(--border);border-radius:var(--radius-card);background:var(--card);box-shadow:var(--shadow-card);overflow:clip}
:global(.bill-series-header){margin:0}
:global(.bill-series-trigger){display:flex;align-items:center;justify-content:space-between;width:100%;gap:16px;min-height:44px;padding:16px;text-align:left;cursor:pointer;color:var(--foreground);background:transparent}
:global(.bill-series-trigger:hover){background:var(--secondary)}
:global(.bill-series-trigger:focus-visible){outline:2px solid var(--ring);outline-offset:-4px}
.bill-series-title{display:grid;gap:4px;min-width:0;overflow-wrap:anywhere}
.bill-series-title strong{font:500 18px var(--font-heading)}
.bill-series-title small{color:var(--muted-foreground);font-weight:400;font-size:12px}
:global(.bill-series-chevron){width:16px;height:16px;flex-shrink:0;transition:transform 160ms ease-out}
:global(.bill-series-trigger[data-state="open"] .bill-series-chevron){transform:rotate(180deg)}
:global(.bill-series-content[data-state="closed"]){display:none}
:global(.bill-series-content[data-state="open"]){animation:series-reveal 180ms ease-out}
.bill-series-items :global([data-slot="card"]){box-shadow:none}
.bill-series-items{display:grid;gap:16px;padding:0 16px 16px}
@keyframes series-reveal{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){:global(.bill-series-chevron){transition:none}:global(.bill-series-content[data-state="open"]){animation:none}}

.forecast-notice{color:var(--text-green);margin:0 0 16px}:global(.series-setting){padding:16px;border:2px solid var(--border);border-radius:var(--radius-input);background:var(--secondary)}.grid{display:grid;grid-template-columns:minmax(250px,350px) minmax(0,1fr);gap:16px;align-items:start}.list{display:grid;gap:16px;min-width:0}.title-row{display:flex;justify-content:space-between;align-items:center;gap:12px}:global(.actions){display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}:global(.submit){margin-top:16px;width:100%}.preference{display:flex;gap:8px;align-items:center;margin-top:16px;font-size:13px;min-height:44px}.preference :global([data-slot="input"]){width:20px;height:20px}:global(.forecast-settings) :global([data-slot="disclosure-trigger"]){cursor:pointer;margin-bottom:12px;color:var(--brand-ink);font-size:13px;min-height:44px}:global(.forecast-settings [data-slot=field-group]){margin-bottom:12px}:global([data-slot="select-trigger"]){width:100%}.grid :global([data-slot=field-group]){gap:12px}@media(max-width:760px){.grid{grid-template-columns:minmax(0,1fr)}}</style>
